from collections import deque
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==1 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); cells=[]
  while q:
   p=q.pop();cells.append(p)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=p[0]+dr,p[1]+dc
    if 0<=rr<R and 0<=cc<C and grid[rr][cc]==col and (rr,cc) not in seen: seen.add((rr,cc));q.append((rr,cc))
  comps.append((col,set(cells)))
def norm(sh):
 mr=min(r for r,c in sh);mc=min(c for r,c in sh);return frozenset((r-mr,c-mc) for r,c in sh)
def included(a,b):
 shape=norm(a)
 br=[r for r,c in b];bc=[c for r,c in b]
 for dr in range(min(br),max(br)+1):
  for dc in range(min(bc),max(bc)+1):
   if all((r+dr,c+dc) in b for r,c in shape):return (dr,dc)
